214	/// Construct an error of ErrT with the given arguments.
215	template <typename ErrT, typename... ArgTs> Error make_error(ArgTs &&...Args) {
216	  static_assert(std::is_base_of<ErrorInfoBase, ErrT>::value,
217	                "ErrT is not an ErrorInfoBase subclass");
218	  return make_error(std::make_unique<ErrT>(std::forward<ArgTs>(Args)...));
219	}
