84	class MockControllerAccess : public Session::ControllerAccess {
85	
86	private:
87	  class ConnectGuard {
88	  public:
89	    ConnectGuard() = default;
90	    ConnectGuard(MockControllerAccess *MCA) : MCA(MCA) {
91	      // Note: Assumes already locked.
92	      ++MCA->Outstanding;
93	    }
94	    ConnectGuard(const ConnectGuard &) = delete;
95	    ConnectGuard &operator=(const ConnectGuard &) = delete;
96	    ConnectGuard(ConnectGuard &&Other) : MCA(Other.MCA) { Other.MCA = nullptr; }
97	    ConnectGuard &operator=(ConnectGuard &&Other) {
98	      reset();
99	      MCA = Other.MCA;
100	      Other.MCA = nullptr;
101	      return *this;
102	    };
103	    ~ConnectGuard() { reset(); }
104	
105	  private:
106	    void reset() {
107	      if (MCA) {
108	        bool Notify;
109	        {
110	          std::scoped_lock Lock(MCA->M);
111	          --MCA->Outstanding;
112	          Notify = MCA->Shutdown && MCA->Outstanding == 0;
113	        }
114	        if (Notify)
115	          MCA->ShutdownCV.notify_all();
116	      }
117	    }
118	    MockControllerAccess *MCA = nullptr;
119	  };
120	
121	public:
122	  using OnConnectFn = move_only_function<Error(BootstrapInfo &BI)>;
123	
124	  /// Hook used to defer controller-side work (the simulated controller
125	  /// handler invocation, and the OnComplete callback for completed calls).
126	  /// Tests typically wire this to push onto the same WorkQueue that the
127	  /// Session's QueueingRunner uses, so that a single drain advances both
128	  /// sides.
129	  using PostFn = move_only_function<void(move_only_function<void()>)>;
130	
131	  MockControllerAccess(Session &SS, PostFn Post = {},
132	                       OnConnectFn OnConnect = {},
133	                       MockControllerAccess **Self = nullptr)
134	      : Session::ControllerAccess(SS), Post(std::move(Post)),
135	        OnConnect(std::move(OnConnect)) {
136	    // Optionally publish this instance so tests that need to drive the
137	    // controller side directly can reach it after attach constructs it.
138	    // (attach constructs the ControllerAccess internally and does not hand
139	    // back a reference, since the object may not outlive the attach call.)
140	    if (Self)
141	      *Self = this;
142	  }
143	
144	  /// Fallible named constructor for testing tryAttach. Returns an error if
145	  /// Fail is true, otherwise a MockControllerAccess forwarding the remaining
146	  /// arguments to the constructor.
147	  static Expected<std::shared_ptr<MockControllerAccess>>
148	  Create(Session &S, bool Fail, PostFn Post = {}, OnConnectFn OnConnect = {}) {
149	    if (Fail)
150	      return make_error<StringError>("failed to create controller access");
151	    return std::make_shared<MockControllerAccess>(S, std::move(Post),
152	                                                  std::move(OnConnect));
153	  }
154	
155	  void connect(BootstrapInfo BI) override {
156	    if (OnConnect) {
157	      if (auto Err = OnConnect(BI)) {
158	        reportError(std::move(Err));
159	        notifyDisconnected();
160	      }
161	    }
162	  }
163	
164	  void disconnect() override {
165	    // Drain any still-pending controller calls before notifying, so their
166	    // handlers are failed rather than silently dropped -- see the
167	    // ControllerAccess::disconnect contract. Shutdown gates callController
168	    // (which bails via failControllerCallInline once it is set), so no new call
169	    // can be registered after the snapshot below.
170	    std::unordered_map<size_t, OnControllerCallReturn> ToDrain;
171	    {
172	      std::unique_lock<std::mutex> Lock(M);
173	      Shutdown = true;
174	      ShutdownCV.wait(Lock, [this]() { return Shutdown && Outstanding == 0; });
175	      ToDrain = std::move(PendingOut);
176	    }
177	    for (auto &[_, OnComplete] : ToDrain)
178	      failPendingControllerCall(std::move(OnComplete));
179	    notifyDisconnected();
180	  }
181	
182	  void callController(OnControllerCallReturn OnComplete,
183	                      orc_rt_ControllerHandlerTag T,
184	                      WrapperFunctionBuffer ArgBytes) override {
185	    // Simulate a call to the controller by running the requested function via
186	    // the test-supplied Post hook (or inline, if no hook was provided).
187	    ConnectGuard CG;
188	    size_t CId = 0;
189	    bool BailOut = false;
190	    {
191	      std::scoped_lock<std::mutex> Lock(M);
192	      if (!Shutdown) {
193	        CG = ConnectGuard(this);
194	        CId = CallId++;
195	        assert(!PendingOut.count(CId));
196	        PendingOut[CId] = std::move(OnComplete);
197	      } else
198	        BailOut = true;
199	    }
200	
201	    if (BailOut)
202	      return failControllerCallInline(std::move(OnComplete));
203	
204	    runOrPost([this, CId, T, ArgBytes = std::move(ArgBytes)]() mutable {
205	      auto Fn = reinterpret_cast<orc_rt_WrapperFunction>(T);
206	      Fn(reinterpret_cast<orc_rt_SessionRef>(this), ArgBytes.release(),
207	         ccReturn, CId);
208	    });
209	  }
210	
211	  void sendWrapperResult(WrapperFunctionBuffer ResultBytes,
212	                         uint64_t CallId) override {
213	    // Respond to a simulated call by the controller.
214	    ConnectGuard CG;
215	    Session::OnControllerCallReturnFn OnComplete;
216	    {
217	      std::scoped_lock<std::mutex> Lock(M);
218	      if (Shutdown) {
219	        assert(PendingIn.empty() && "Shut down but results still pending?");
220	        return;
221	      }
222	      CG = ConnectGuard(this);
223	      auto I = PendingIn.find(CallId);
224	      assert(I != PendingIn.end());
225	      OnComplete = std::move(I->second);
226	      PendingIn.erase(I);
227	    }
228	
229	    runOrPost([OnComplete = std::move(OnComplete),
230	               ResultBytes = std::move(ResultBytes)]() mutable {
231	      OnComplete(std::move(ResultBytes));
232	    });
233	  }
234	
235	  void returnFromController(uint64_t CallId,
236	                            WrapperFunctionBuffer ResultBytes) {
237	    ConnectGuard CG;
238	    OnControllerCallReturn OnComplete;
239	    {
240	      std::scoped_lock<std::mutex> Lock(M);
241	      CG = ConnectGuard(this);
242	      auto I = PendingOut.find(CallId);
243	      assert(I != PendingOut.end());
244	      OnComplete = std::move(I->second);
245	      PendingOut.erase(I);
246	    }
247	
248	    handleControllerCallResult(std::move(OnComplete), std::move(ResultBytes));
249	  }
250	
251	  void callFromController(Session::OnControllerCallReturnFn OnComplete,
252	                          orc_rt_WrapperFunction Fn,
253	                          WrapperFunctionBuffer ArgBytes) {
254	    ConnectGuard CG;
255	    size_t CId = 0;
256	    bool BailOut = false;
257	    {
258	      std::scoped_lock<std::mutex> Lock(M);
259	      if (!Shutdown) {
260	        CG = ConnectGuard(this);
261	        CId = CallId++;
262	        PendingIn[CId] = std::move(OnComplete);
263	      } else
264	        BailOut = true;
265	    }
266	    if (BailOut)
267	      return runOrPost([OnComplete = std::move(OnComplete)]() mutable {
268	        OnComplete(WrapperFunctionBuffer::createOutOfBandError(
269	            "Controller disconnected"));
270	      });
271	
272	    handleWrapperCall(Fn, std::move(ArgBytes), CId);
273	  }
274	
275	private:
276	  void runOrPost(move_only_function<void()> Work) {
277	    if (Post)
278	      Post(std::move(Work));
279	    else
280	      Work();
281	  }
282	
283	  static void ccReturn(orc_rt_SessionRef S,
284	                       orc_rt_WrapperFunctionBuffer ResultBytes,
285	                       uint64_t CallId) {
286	    // Abuse "session" to refer to the ControllerAccess object.
287	    // We can just re-use sendFunctionResult for this.
288	    reinterpret_cast<MockControllerAccess *>(S)->returnFromController(
289	        CallId, WrapperFunctionBuffer(ResultBytes));
290	  }
291	
292	  PostFn Post;
293	
294	  std::mutex M;
295	  bool Shutdown = false;
296	  size_t CallId = 0;
297	  size_t Outstanding = 0;
298	  std::unordered_map<size_t, OnControllerCallReturn> PendingOut;
299	  std::unordered_map<size_t, Session::OnControllerCallReturnFn> PendingIn;
300	  std::condition_variable ShutdownCV;
301	  OnConnectFn OnConnect;
302	};
303	
304	class CallFromController {
305	public:
306	  CallFromController(MockControllerAccess &CA, orc_rt_WrapperFunction Fn)
307	      : CA(CA), Fn(Fn) {}
308	  void operator()(Session::OnControllerCallReturnFn OnComplete,
309	                  WrapperFunctionBuffer ArgBytes) {
310	    CA.callFromController(std::move(OnComplete), Fn, std::move(ArgBytes));
311	  }
312	
313	private:
314	  MockControllerAccess &CA;
315	  orc_rt_WrapperFunction Fn;
316	};
