492	  // can't get a new token.
493	  ASSERT_FALSE(TaskGroup::Token(S.managedCodeTokenSource()));
494	
495	  Tok = TaskGroup::Token(); // Reset token.
496	
497	  EXPECT_EQ(ShutdownOpIdx, 1U);
