629	// A ControllerAccess that is attached but whose controller connection is
630	// already gone, so every callController fails synchronously. Used to exercise
631	// the failControllerCallInline path in isolation.
632	class DeadControllerAccess : public Session::ControllerAccess {
633	public:
634	  DeadControllerAccess(Session &S) : ControllerAccess(S) {}
635	  void connect(BootstrapInfo) override {}
636	  void disconnect() override { notifyDisconnected(); }
637	  void callController(OnControllerCallReturn OnComplete,
638	                      orc_rt_ControllerHandlerTag,
639	                      WrapperFunctionBuffer) override {
640	    failControllerCallInline(std::move(OnComplete));
641	  }
642	  void sendWrapperResult(WrapperFunctionBuffer, uint64_t) override {}
643	};
