645	TEST(ControllerAccessTest, SynchronousCallControllerFailureRunsInline) {
646	  // A controller call that fails synchronously (connection already gone) must
647	  // complete its handler inline -- on the calling thread, before callController
648	  // returns, and WITHOUT going through Dispatch -- with the canonical
649	  // "disconnected" out-of-band error. noDispatch ADD_FAILUREs if anything is
650	  // dispatched, so it doubles as the "ran inline, not via the task queue"
651	  // check.
652	  Session S(mockExecutorProcessInfo(), noDispatch, noErrors);
653	  S.attach<DeadControllerAccess>(BootstrapInfo(S));
654	
655	  bool HandlerRan = false;
656	  std::string ErrMsg;
657	  S.callController(
658	      [&](WrapperFunctionBuffer Result) {
659	        HandlerRan = true;
660	        if (const char *E = Result.getOutOfBandError())
661	          ErrMsg = E;
662	      },
663	      /*T=*/nullptr, WrapperFunctionBuffer());
664	
665	  // Set synchronously, during the call above -> the handler ran inline.
666	  EXPECT_TRUE(HandlerRan);
667	  EXPECT_EQ(ErrMsg, "disconnected");
668	}
