804	// Stashes Return, via the address passed as the wrapper call's argument,
805	// instead of calling it -- simulating a wrapper function that defers
806	// completion past its own return.
807	static void deferred_wrapper(orc_rt_SessionRef S,
808	                             orc_rt_WrapperFunctionBuffer ArgBytes,
809	                             orc_rt_WrapperFunctionReturn Return,
810	                             uint64_t CallId) {
811	  SPSWrapperFunction<void(SPSExecutorAddr)>::handle(
812	      S, ArgBytes, Return, CallId,
813	      [](move_only_function<void()> Return, ExecutorAddr P) {
