818	TEST(ControllerAccessTest, WrapperCallTokenReleasedWhenFnReturns) {
819	  // A managed-code token acquired for an incoming wrapper call must bracket
820	  // only the (synchronous) span of Fn's execution -- not the whole
821	  // call/response chain -- per the "Managed code execution and shutdown"
822	  // policy in docs/Design.md. Check this by having Fn defer its Return call
823	  // past its own return, then confirming that Session shutdown's drain phase
824	  // does not wait on that deferred call.
825	  QueueingRunner<>::WorkQueue Tasks;
826	  Session S(mockExecutorProcessInfo(), QueueingRunner(Tasks), noErrors);
827	  MockControllerAccess *CA = nullptr;
828	  S.attach<MockControllerAccess>(BootstrapInfo(S), postOnto(Tasks),
829	                                 MockControllerAccess::OnConnectFn{}, &CA);
830	
831	  move_only_function<void()> DeferredReturn;
832	
833	  bool GotResult = false;
834	  SPSWrapperFunction<void(SPSExecutorAddr)>::call(
835	      CallFromController(*CA, deferred_wrapper),
836	      [&](Error Err) {
837	        cantFail(std::move(Err));
838	        GotResult = true;
839	      },
840	      &DeferredReturn);
841	
842	  QueueingRunner<>::runFIFOUntilEmpty(Tasks);
843	
844	  // Fn ran and deferred its Return call, so no result should have been sent
845	  // back yet.
846	  ASSERT_TRUE(DeferredReturn);
847	  EXPECT_FALSE(GotResult);
848	
849	  // Fn has already returned, so its managed-code token should have been
850	  // released even though the call is still logically outstanding. Shutdown's
851	  // drain phase should therefore complete without waiting on the deferred
852	  // Return call.
853	  bool ShutdownComplete = false;
854	  S.shutdown([&] { ShutdownComplete = true; });
855	  EXPECT_TRUE(ShutdownComplete);
856	}
